package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.service.PlantService;import org.nonfood.oilplants.util.ResultFields;import java.io.*;import java.util.logging.Level;import java.util.logging.Logger;
@WebServlet("/search/advanced") public class AdvancedSearchServlet extends HttpServlet{private static final Logger LOG=Logger.getLogger(AdvancedSearchServlet.class.getName());protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{var svc=new PlantService();var c=svc.criteria(r.getParameterMap());r.setAttribute("criteria",c);r.setAttribute("pageData",svc.dao().search(c,false));r.setAttribute("fields",ResultFields.validate(r.getParameterValues("field")));}catch(IllegalArgumentException e){r.setAttribute("error",e.getMessage());r.setAttribute("fields",ResultFields.DEFAULT);}catch(Exception e){LOG.log(Level.SEVERE,"Advanced search failed",e);s.setStatus(HttpServletResponse.SC_SERVICE_UNAVAILABLE);r.setAttribute("error","高级查询暂时不可用。请稍后重试，或检查数据库连接状态。");r.setAttribute("fields",ResultFields.DEFAULT);}WebSupport.view(r,s,"plants/advanced");}}
